149	        OP_LOGI(context->GetNodeName(), "attrsPtr is nullptr");
150	        return GRAPH_SUCCESS;
151	    }
152	
153	    const int64_t* dstDtype = attrsPtr->GetAttrPointer<int64_t>(ATTR_2_IDX);
154	    if (dstDtype == nullptr) {
155	        OP_LOGI(context->GetNodeName(), "dstDtype is not configed");
156	        return GRAPH_SUCCESS;
157	    }
158	
159	    ge::DataType outDtype = static_cast<ge::DataType>(*dstDtype);
160	    OP_LOGD(context->GetNodeName(), "dtype in attrs is %ld", (int64_t)outDtype);
161	    OP_CHECK_IF(!(outDtype == ge::DT_FLOAT || outDtype == ge::DT_FLOAT16 || outDtype == ge::DT_BF16 ||
162	                  outDtype == ge::DT_UINT8),
163	                OP_LOGE(context->GetNodeName(), "dtype should be float32, float16, bfloat16 or uint8."),
