170	                return GRAPH_FAILED);
171	    OP_CHECK_IF(
172	        ((xDtype == ge::DT_FLOAT16 && outDtype == ge::DT_BF16) ||
173	         (xDtype == ge::DT_BF16 && outDtype == ge::DT_FLOAT16)),
174	        OP_LOGE(context->GetNodeName(), "xDtype is float16 or bfloat16, outDtype should be same to xDtype or float32."),
175	        return GRAPH_FAILED);
176	
177	    OP_LOGI(context->GetNodeName(), "set output to configed dtype: %s", Ops::Base::ToString(outDtype).c_str());
178	    context->SetOutputDataType(0, outDtype);
179	    OP_LOGD(context->GetNodeName(), "Do InferDtype4ResizeBilinearV2 success");
180	    return GRAPH_SUCCESS;
181	}
